package greeter

import "strings"

// Slug 把名字转成 URL 友好的 slug，用于页面锚点：
// 输出小写（大小写不敏感）、空白折成单个连字符、首尾不留连字符。
// 名字为空白时返回空串。
func Slug(name string) string {
	return strings.ToLower(strings.Join(strings.Fields(name), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"lowercases", "Ada Lovelace", "ada-lovelace"},
		{"collapses whitespace", "Ada \t\n Lovelace", "ada-lovelace"},
		{"trims edges", "  Ada Lovelace  ", "ada-lovelace"},
		{"single word", "Ada", "ada"},
		{"empty", "", ""},
		{"whitespace only", " \t\n ", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := Slug(tc.in); got != tc.want {
				t.Fatalf("Slug(%q) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

func TestSlugCaseInsensitive(t *testing.T) {
	if got, want := Slug("ADA LOVELACE"), Slug("ada lovelace"); got != want {
		t.Fatalf("case variants differ: %q vs %q", got, want)
	}
}
